insert into public.rule_versions (rule_card_id, version, status, risk_level, title, description, risky_examples, match_patterns, safe_replacements, flag_trigger, safe_fix, source_org, source_title, source_url, source_reference, effective_date, last_verified_at, verification_note, legal_review_status) values ('TR-RY-YZ-DIJITAL-KOPYA', 1, 'active', 'high', 'Gerçek kişinin yapay zekâ ile üretilmiş dijital kopyası', 'Gerçek bir kişinin yapay zekâ ile oluşturulmuş dijital kopyası, o kişi ürünü gerçekten kullanmış veya tavsiye etmiş gibi reklamda kullanılamaz.', array['Ünlü bir kişinin YZ ile üretilmiş görüntüsüyle ''ben de kullanıyorum'' mesajı']::text[], '{}'::text[], '[]'::jsonb, 'ai_real_person_copy', 'Gerçek kişinin dijital kopyasını kaldırın. Gerçek bir tavsiye varsa yazılı izin ve belgesi olmalı.', 'T.C. Ticaret Bakanlığı', 'Ticari Reklam ve Haksız Ticari Uygulamalar Yönetmeliğinde değişiklik (RG 01.07.2026, sayı 33297) – Bakanlık duyurusu', 'https://ticaret.gov.tr/haberler/ticaret-bakanligi-tarafindan-ticari-reklam-ve-haksiz-ticari-uygulamalar-yonetmeliginde-yapilan-degisikliklerle-tuketicilerin-aldatici-reklam-ve-ticari-uygulamalara-karsi-korunmasi-guclendiriliyor', 'Ticari Reklam ve Haksız Ticari Uygulamalar Yönetmeliği md. 27/12 (yeni)', '2026-08-01'::date, '2026-11-16'::date, 'Değişikliğin özü Ticaret Bakanlığı''nın 01.07.2026 tarihli resmî duyurusunda okundu. Madde numarası RÖK karşılaştırma tablosundan alındı; Resmî Gazete metni bu ortamdan okunamadı, hukukçu teyidi bekliyor.', 'pending')
  on conflict (rule_card_id, version) do nothing;

