insert into public.rule_versions (rule_card_id, version, status, risk_level, title, description, risky_examples, match_patterns, safe_replacements, flag_trigger, safe_fix, source_org, source_title, source_url, source_reference, effective_date, last_verified_at, verification_note, legal_review_status) values ('TR-6502-USTUNLUK', 1, 'requires_review', 'high', 'Kanıtlanmamış üstünlük / birincilik iddiası', '''En iyi'', ''Türkiye''nin 1 numarası'', ''en etkili'' gibi iddialar belgelendirilmedikçe aldatıcı reklam riski taşır. İlgili kanun/yönetmelik metni bu doğrulamada okunamadı.', array['Türkiye''nin en etkili detoks çayı', 'Sektörün 1 numarası', 'En iyi fiyat garantisi']::text[], array['\ben\s+(iyi|etkili|ucuz|kaliteli|guvenilir|hizli|guclu)\w*', '(1|bir)\s*numara\w*', '\blider\b', 'turkiye''?nin\s+(\S+\s+)?(en|ilk|1)']::text[], '[{"pattern":"turkiye''?nin\\s+en\\s+(iyi|etkili|kaliteli|guvenilir)\\w*","replacement":"özenle hazırlanan"},{"pattern":"\\ben\\s+(iyi|etkili|kaliteli|guvenilir|guclu)\\w*","replacement":"özenle seçilmiş"},{"pattern":"(sektorun\\s+)?(1|bir)\\s*numara\\w*","replacement":"tercih edilen"}]'::jsonb, null, 'Bağımsız ve güncel bir kanıt yoksa üstünlük ifadesini kaldırın veya ölçülebilir bir özellikle değiştirin.', 'T.C. Mevzuat Bilgi Sistemi', '6502 sayılı Tüketicinin Korunması Hakkında Kanun', 'https://www.mevzuat.gov.tr/mevzuat?MevzuatNo=6502&MevzuatTur=1&MevzuatTertip=5', '6502 s. Kanun md. 61; Ticari Reklam Yönetmeliği md. 7 (teyit edilmedi)', null, '2026-11-16'::date, 'Resmî metin (mevzuat.gov.tr) bu ortamdan okunamadı. Hukukçu teyidinden sonra ''active'' yapılabilir.', 'pending')
  on conflict (rule_card_id, version) do nothing;

