insert into public.rule_versions (rule_card_id, version, status, risk_level, title, description, risky_examples, match_patterns, safe_replacements, flag_trigger, safe_fix, source_org, source_title, source_url, source_reference, effective_date, last_verified_at, verification_note, legal_review_status) values ('TR-RY-SAGLIK-BEYANI', 1, 'requires_review', 'high', 'Mevzuata aykırı sağlık beyanı', 'İlgili mevzuatına aykırı olarak bir mal veya hizmet hakkında sağlık beyanında bulunmak haksız ticari uygulama sayılabilir (''zayıflatır'', ''bağışıklığı güçlendirir'' vb.). Resmî metin bu doğrulamada okunamadı.', array['Zayıflatır', 'Bağışıklığı güçlendirir', 'Yağ yakar', 'Detoks yapar']::text[], array['zayiflat\w*', 'kilo ver\w*', 'yag yak\w*', 'bagisiklig\w*\s+(\S+\s+)?(guclendir|arttir)\w*', 'detoks\w*', 'metabolizma\w*\s+(\S+\s+)?hizlandir\w*']::text[], '[{"pattern":"zayiflat\\w*","replacement":"dengeli beslenmenize eşlik eder"},{"pattern":"yag yak\\w*","replacement":"aktif yaşamınıza eşlik eder"},{"pattern":"kilo ver\\w*","replacement":"kendinize iyi bakın"}]'::jsonb, null, 'Onaylı bir sağlık beyanı yoksa ürünün sağlık etkisini değil, içeriğini ve kullanım anını anlatın.', 'T.C. Resmî Gazete', 'Ticari Reklam ve Haksız Ticari Uygulamalar Yönetmeliğinde Değişiklik Yapılmasına Dair Yönetmelik', 'https://www.resmigazete.gov.tr/eskiler/2026/07/20260701-9.htm', 'Yönetmelik eki haksız ticari uygulamalar listesi, madde 13 (ikincil kaynağa göre; teyit edilmedi)', '2026-08-01'::date, '2026-11-16'::date, 'Resmî Gazete metni bu ortamdan okunamadı; madde yalnızca ikincil kaynakta görüldü.', 'pending')
  on conflict (rule_card_id, version) do nothing;

