insert into public.rule_versions (rule_card_id, version, status, risk_level, title, description, risky_examples, match_patterns, safe_replacements, flag_trigger, safe_fix, source_org, source_title, source_url, source_reference, effective_date, last_verified_at, verification_note, legal_review_status) values ('TR-ESTETIK-ONCE-SONRA', 1, 'requires_review', 'high', 'Sağlık hizmetinde önce/sonra ve hasta beyanı', 'Sağlık kuruluşları ve meslek mensuplarının tanıtımında önce/sonra görselleri, hasta yorumları ve sonuç vaatleri ayrı bir sağlık mevzuatıyla sınırlanır. Bu düzenlemenin resmî metni bu doğrulamada bulunamadı.', array['Hastalarımızın önce/sonra fotoğrafları', 'Memnun hastalarımız anlatıyor']::text[], array['hasta\w*\s+(\S+\s+){0,2}(once|sonra|yorum|anlatiyor|memnun)', '\bonce(si)?\s*(/|-|ve|&)\s*sonra(si)?\b']::text[], '[]'::jsonb, null, 'Önce/sonra ve hasta beyanlarını kullanmayın; hizmeti bilgilendirici ve tarafsız biçimde anlatın. Güncel Sağlık Bakanlığı düzenlemesini kontrol edin.', 'T.C. Sağlık Bakanlığı', 'Sağlık Bakanlığı yönetmelikler listesi', 'https://www.saglik.gov.tr/TR-10413/yonetmelikler.html', null, null, '2026-11-16'::date, 'Sağlık hizmetleri tanıtım düzenlemesi resmî listede bu doğrulamada bulunamadı. Hukukçu incelemesi şart.', 'pending')
  on conflict (rule_card_id, version) do nothing;

insert into public.rule_cards (id, domain, category, sector) values ('TR-ESTETIK-FIYAT-KAMPANYA', 'tr_law', 'Sağlık hizmetleri tanıtımı', 'estetik_klinik')
