insert into public.rule_versions (rule_card_id, version, status, risk_level, title, description, risky_examples, match_patterns, safe_replacements, flag_trigger, safe_fix, source_org, source_title, source_url, source_reference, effective_date, last_verified_at, verification_note, legal_review_status) values ('TR-ESTETIK-FIYAT-KAMPANYA', 1, 'requires_review', 'medium', 'Sağlık hizmetinde fiyat/kampanya duyurusu', 'Sağlık hizmetlerinde indirim ve kampanya ilanı ayrı kısıtlara tabi olabilir. Resmî metin bu doğrulamada okunamadı.', array['Botoksa %40 indirim', 'Kampanyalı burun estetiği']::text[], array['(dolgu|botoks|botox|estetig\w*|lazer|epilasyon|sac ekimi)\w*\s+(\S+\s+){0,3}(indirim|kampanya|firsat)', '(indirim|kampanya|firsat)\w*\s+(\S+\s+){0,3}(dolgu|botoks|botox|estetig\w*|sac ekimi)']::text[], '[]'::jsonb, null, 'Sağlık hizmetinde fiyat ve kampanya duyurusu yapmadan önce güncel Sağlık Bakanlığı düzenlemesini ve meslek kuruluşu kurallarını kontrol edin.', 'T.C. Sağlık Bakanlığı', 'Sağlık Bakanlığı yönetmelikler listesi', 'https://www.saglik.gov.tr/TR-10413/yonetmelikler.html', null, null, '2026-11-16'::date, 'Resmî metin bulunamadı. Hukukçu incelemesi şart.', 'pending')
  on conflict (rule_card_id, version) do nothing;

